Given a 2D grid of size n*n, where each cell represents the cost to traverse through that cell, the task is to find the minimum cost to move from the top left cell to the bottom right cell. From a given cell, we can move in 4 directions: left, right, up, down.Note: It is assumed that negative cost cycles do not exist in input matrix.Example:Input: grid = {{9, 4, 9, 9},                        {6, 7, 6, 4},                       {8, 3, 3, 7},                      {7, 4, 9, 10}}Output: 43Explanation: The minimum cost path is 9 + 4 + 7 + 3 + 3 + 7 + 10.Try It YourselfApproach:The idea is to use Dijkstra's algorithm to find the minimum cost path through the grid. This approach treats the grid as a graph where each cell is a node, and the algorithm dynamically explores the most cost-effective path to the bottom-right cell by always expanding the lowest-cost paths first.Step by step approach:Use a min-heap to always process the lowest-cost path first and push the top left cell into it.Initialize a cost matrix with maximum values, setting the start cell's cost to its grid value.For each cell, check all 4 neighboring cellsIf a lower cost path is found, then update the cost of cell and push it into heap.Return the minimum cost to reach the bottom-right cell.Below is the implementation of the above approach:
            C++

    // C++ program to find minimum Cost Path with 
// Left, Right, Bottom and Up moves allowed
#include <bits/stdc++.h>
using namespace std;

// Function to check if cell is valid.
bool isValidCell(int i, int j, int n) {
    return i>=0 && i<n && j>=0 && j<n;
}

int minimumCostPath(vector<vector<int>> &grid) {
    int n = grid.size();

    // Min heap to implement dijkstra
    priority_queue<vector<int>, 
    vector<vector<int>>, greater<vector<int>>> pq;

    // 2d grid to store minimum cost
    // to reach every cell.
    vector<vector<int>> cost(n, vector<int>(n, INT_MAX));
    cost[0][0] = grid[0][0];

    // Direction vector to move in 4 directions
    vector<vector<int>> dir = {{-1,0}, {1,0}, {0,-1}, {0,1}};

    pq.push({grid[0][0], 0, 0});

    while (!pq.empty()) {
        vector<int> top = pq.top();
        pq.pop();

        int c = top[0], i = top[1], j = top[2];

        // Check for all 4 neighbouring cells.
        for (auto d: dir) {
            int x = i + d[0];
            int y = j + d[1];

            // If cell is valid and cost to reach this cell 
            // from current cell is less
            if (isValidCell(x, y, n) && 
            cost[i][j]+grid[x][y]<cost[x][y]) {

                // Update cost to reach this cell.
                cost[x][y] = cost[i][j]+grid[x][y];

                // Push the cell into heap.
                pq.push({cost[x][y], x, y});
            }
        }
    }

    // Return minimum cost to 
    // reach bottom right cell.
    return cost[n-1][n-1];
}

int main() {
    vector<vector<int>> grid = 
    {{9,4,9,9},{6,7,6,4},{8,3,3,7},{7,4,9,10}};

    cout << minimumCostPath(grid) << endl;

    return 0;
}


